    38	export function evaluateToolPermission(request: ToolPermissionRequest): ToolPermissionDecision {
    39		const { tool, surface, provenance } = request;
    40		const reasons: string[] = [];
    41		const untrusted = isUntrustedProvenance(provenance);
    42		const independentlyAuthorized = hasIndependentUserAuthorization(provenance);
    43		const secretBearing = tool.sensitiveArguments === true || containsLikelySecret(request.arguments);
    44	
    45		if (surface === "voice" && (tool.allowVoice === false || NEVER_VOICE.has(tool.risk))) {
    46			return decision("deny", tool.risk, ["This tool is not permitted from voice input."], true);
    47		}
    48	
    49		if (surface === "voice" && secretBearing) {
    50			return decision("deny", tool.risk, ["Secret-bearing arguments are not permitted from voice input."], true);
    51		}
    52	
    53		if (untrusted && !independentlyAuthorized) {
    54			if (tool.risk === "code-execution" || tool.risk === "destructive") {
    55				return decision("deny", tool.risk, ["Untrusted web content cannot authorize code execution or destructive actions."], true);
    56			}
    57			if (tool.risk !== "informational") {
    58				reasons.push("Untrusted web content cannot independently authorize this action.");
    59			}
    60		}
    61	
    62		if (ALWAYS_CONFIRM.has(tool.risk)) reasons.push(`Risk class ${tool.risk} requires confirmation.`);
    63		if (tool.risk === "state-change" && (surface !== "text" || untrusted)) {
    64			reasons.push("State changes require confirmation on this surface or provenance.");
    65		}
    66		if (tool.risk === "sensitive-read" && (untrusted || surface === "voice")) {
    67			reasons.push("Sensitive reads require confirmation on this surface or provenance.");
    68		}
