     3	export function combineContentTrust(values: readonly ContentTrust[]): ContentTrust {
     4		if (values.length === 0) return "unknown";
     5		const distinct = new Set(values);
     6		if (distinct.size === 1) return values[0] ?? "unknown";
     7		if (distinct.has("untrusted-web") || distinct.has("mixed")) return "mixed";
     8		return distinct.has("unknown") ? "unknown" : "mixed";
