     1	const SENSITIVE_KEY = /(?:api[-_]?key|authorization|cookie|credential|password|secret|session|token)/i;
     2	const SECRET_VALUE_PATTERNS = [
     3		/\bsk-[A-Za-z0-9_-]{12,}\b/g,
     4		/\bBearer\s+[A-Za-z0-9._~+\/-]+=*\b/gi,
     5		/\b(?:ghp|github_pat)_[A-Za-z0-9_]{12,}\b/g,
     6	] as const;
     7	
     8	export const REDACTED = "[REDACTED]";
     9	
    10	export function redactString(value: string): string {
    11		return SECRET_VALUE_PATTERNS.reduce(
    12			(redacted, pattern) => redacted.replace(pattern, REDACTED),
    13			value,
    14		);
    15	}
    16	
    17	export function redactSecrets(value: unknown, seen = new WeakSet<object>()): unknown {
    18		if (typeof value === "string") return redactString(value);
    19		if (value === null || typeof value !== "object") return value;
    20		if (seen.has(value)) return "[CIRCULAR]";
    21		seen.add(value);
    22	
    23		if (Array.isArray(value)) return value.map((item) => redactSecrets(item, seen));
    24	
    25		const output: Record<string, unknown> = {};
    26		for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    27			output[key] = SENSITIVE_KEY.test(key) ? REDACTED : redactSecrets(item, seen);
    28		}
    29		return output;
    30	}
    31	
    32	export function containsLikelySecret(value: unknown): boolean {
    33		if (typeof value === "string") {
    34			return SECRET_VALUE_PATTERNS.some((pattern) => {
    35				pattern.lastIndex = 0;
    36				return pattern.test(value);
    37			});
    38		}
    39		if (value === null || typeof value !== "object") return false;
    40		if (Array.isArray(value)) return value.some(containsLikelySecret);
    41		return Object.entries(value as Record<string, unknown>).some(
    42			([key, item]) => SENSITIVE_KEY.test(key) || containsLikelySecret(item),
    43		);
    44	}

