    73	export function resolveProviderWebSearchRoute(
    74		model: Model<Api>,
    75		hasApiKey: boolean,
    76	): SearchRoute {
    77		const negotiation = negotiateProviderCapabilities(model, {
    78			webSearch: true,
    79			citations: true,
    80			allowAdapters: true,
    81		});
    82		const available = enabled(hasApiKey);
    83		const kind = !available
    84			? "unavailable"
    85			: negotiation.webSearch === "native"
