    87				: negotiation.webSearch === "adapter"
    88					? "client-adapter"
    89					: "unavailable";
    90		return {
    91			provider: model.provider,
    92			modelId: model.id,
    93			kind,
    94			tool: kind === "unavailable" ? undefined : negotiation.searchTool,
    95			citationKind: kind === "unavailable" ? undefined : negotiation.capabilities.citationKind,
    96			providerNative: kind === "native",
    97		};
    98	}
