   100	/** Add the active provider's hosted search tool without disturbing app tools. */
   101	export function applyProviderWebSearch(payload: unknown, model: Model<Api>, hasApiKey: boolean): unknown | undefined {
   102		const route = resolveProviderWebSearchRoute(model, hasApiKey);
   103		switch (route.tool) {
   104			case "google-search-grounding": return applyGoogleSearchGrounding(payload, model, hasApiKey);
   105			case "openai-web-search": return applyOpenAiWebSearch(payload, model, hasApiKey);
   106			case "anthropic-web-search": return applyAnthropicWebSearch(payload, model, hasApiKey);
   107			// Client adapters are app tools; never pretend they are provider-hosted
   108			// by injecting them into an unknown provider's request payload.
   109			case "client-web-search":
   110			default: return undefined;
   111		}
