    18		id?: () => string;
    19	}
    20	
    21	const fallbackId = () => typeof crypto !== "undefined" && "randomUUID" in crypto
    22		? crypto.randomUUID()
    23		: `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    24	
    25	export function createConversationRuntime(options: ConversationRuntimeOptions): ConversationRuntime {
    26		const now = options.now ?? (() => new Date());
    27		const id = options.id ?? fallbackId;
    28		let runId = options.runId ?? id();
    29		let sequence = Math.max(-1, ...options.store.replay(options.sessionId).events.map((event) => event.sequence));
