    42					sequence: ++sequence,
    43					timestamp: now().toISOString(),
    44					sessionId: options.sessionId,
    45					runId,
    46				});
    47				accept(event);
    48				if (event.type === "ui.action") {
    49					options.store.putPendingAction({ sessionId: event.sessionId, runId: event.runId, action: event.payload.action, createdAt: event.timestamp });
